/**
 * vendor-pele
 *
 * Copies Pele's browser build from the pinned `pele` npm package to
 * public/app/common/pele/, where the editor loads it to render Mermaid diagrams.
 * The server and CLI import the same package, so browser and server renderings
 * always come from one version.
 *
 * Like the EdiCuaTeX tree, the copy is gitignored and generated by build:all.
 *
 *   bun scripts/vendor-pele.ts            # rewrite the copy
 *   bun scripts/vendor-pele.ts --check    # fail if the copy has drifted
 */

import fs from 'node:fs';
import path from 'node:path';
import { type CliIo, detectDrift, type VendorPlanEntry, writeVendoredTree } from './vendor-edicuatex';

/** The self-contained IIFE build (exposes `window.pele`) and its licence. */
const VENDORED_FILES = [
    { relativePath: 'pele.global.js', source: ['dist', 'pele.global.js'] },
    { relativePath: 'LICENSE', source: ['LICENSE'] },
] as const;

export function buildVendorPlan(packageRoot: string): VendorPlanEntry[] {
    return VENDORED_FILES.map(({ relativePath, source }) => ({
        relativePath,
        sourcePath: path.join(packageRoot, ...source),
    }));
}

export function resolvePaths(repoRoot: string): { packageRoot: string; targetRoot: string } {
    return {
        packageRoot: path.join(repoRoot, 'node_modules', 'pele'),
        targetRoot: path.join(repoRoot, 'public', 'app', 'common', 'pele'),
    };
}

const consoleIo: CliIo = { log: m => console.log(m), error: m => console.error(m) };

/** Runs the command and returns the process exit code. */
export function run(argv: string[], repoRoot: string, io: CliIo = consoleIo): number {
    const { packageRoot, targetRoot } = resolvePaths(repoRoot);

    if (!fs.existsSync(packageRoot)) {
        io.error('node_modules/pele is missing. Run `make deps` first.');
        return 1;
    }

    const version = JSON.parse(fs.readFileSync(path.join(packageRoot, 'package.json'), 'utf8')).version;
    const plan = buildVendorPlan(packageRoot);

    if (argv.includes('--check')) {
        const drift = detectDrift(plan, targetRoot);
        if (drift.missing.length + drift.extra.length + drift.changed.length === 0) {
            io.log(`public/app/common/pele is in sync with pele@${version}.`);
            return 0;
        }
        io.error(`public/app/common/pele has drifted from pele@${version}:`);
        for (const file of drift.missing) io.error(`  missing  ${file}`);
        for (const file of drift.extra) io.error(`  extra    ${file}`);
        for (const file of drift.changed) io.error(`  changed  ${file}`);
        io.error('\nRun `bun run vendor:pele` to regenerate it.');
        return 1;
    }

    writeVendoredTree(plan, targetRoot);
    io.log(`Vendored pele@${version} into public/app/common/pele.`);
    return 0;
}

if (import.meta.main) {
    process.exit(run(process.argv.slice(2), path.resolve(import.meta.dir, '..')));
}
